$root = (Resolve-Path "$PSScriptRoot\..\..").Path; $legacyData = Join-Path $env:USERPROFILE '.avatarkit'; if (-not $env:AVATARKIT_HOME -or $env:AVATARKIT_HOME -eq $legacyData) { $env:AVATARKIT_HOME = Join-Path $root 'backend\.avatarkit' }; foreach ($name in 'cache','temp') { $path = Join-Path $env:AVATARKIT_HOME $name; if (Test-Path $path) { Get-ChildItem -Force $path | Remove-Item -Recurse -Force } }; Write-Host 'Cleared AvatarKit cache and temporary files only.'
